# ==============================================================================
# Tytul:        parse_results.py
# Opis:         Parser wynikow EXPLAIN (FORMAT JSON) z benchmarku Async I/O.
#               Odczytuje pliki JSON wygenerowane przez run_benchmark.sh,
#               wyodrebnia Execution Time, Shared Hit/Read Blocks
#               i generuje plik SQL z instrukcjami INSERT.
# Description [EN]: Parser for EXPLAIN (FORMAT JSON) benchmark results.
#               Reads JSON files generated by run_benchmark.sh,
#               extracts Execution Time, Shared Hit/Read Blocks,
#               and generates a SQL file with INSERT statements.
#
# Autor:        KCB Kris
# Data:         2026-04-01
# Wersja:       1.0
#
# Wymagania [PL]:    - Python 3.8+
#                    - Pliki output_*.json wygenerowane przez run_benchmark.sh
# Requirements [EN]: - Python 3.8+
#                    - output_*.json files generated by run_benchmark.sh
#
# Uzycie [PL]:       python3 agent/parse_results.py
# Usage [EN]:        python3 agent/parse_results.py
# ==============================================================================

import json
import os
import re

def parse_explain(file_path):
    with open(file_path, 'r') as f:
        # psql might have inserted '+\n' and extra spaces
        content = f.read()
        # remove trailing spaces and '+' at the end of lines
        content = re.sub(r' \+\n', '\n', content)
        content = re.sub(r'\+\n', '\n', content)
        # remove any leading lines that are empty
        data = json.loads(content)
        plan = data[0]['Plan']
        exec_time = data[0]['Execution Time']
        shared_hit = plan.get('Shared Hit Blocks', 0)
        shared_read = plan.get('Shared Read Blocks', 0)
        return exec_time, shared_hit, shared_read

def parse_vacuum(file_path):
    with open(file_path, 'r') as f:
        content = f.read()
        match = re.search(r'system usage:.*?elapsed.*? ([\d\.]+) s', content)
        if match:
            return float(match.group(1)) * 1000  # to ms
        return 0

results = []

for port, io_method in [(5416, 'sync'), (5432, 'worker')]:
    for run in [1, 2, 3]:
        # Seq Scan
        try:
            et, hit, read = parse_explain(f'output_seq_{port}_{run}.json')
            results.append(f"INSERT INTO benchmark.pomiary (io_method, test_name, run_no, czas_ms, shared_hit, shared_read, uwagi) VALUES ('{io_method}', 'Sequential Scan', {run}, {et}, {hit}, {read}, 'Run {run}');")
        except Exception as e:
            print(f"Error parsing seq scan {port} run {run}: {e}")
        
        # Bitmap Scan
        try:
            et, hit, read = parse_explain(f'output_bit_{port}_{run}.json')
            results.append(f"INSERT INTO benchmark.pomiary (io_method, test_name, run_no, czas_ms, shared_hit, shared_read, uwagi) VALUES ('{io_method}', 'Bitmap Heap Scan', {run}, {et}, {hit}, {read}, 'Run {run}');")
        except Exception as e:
            print(f"Error parsing bit scan {port} run {run}: {e}")
        
    # Vacuum
    try:
        et = parse_vacuum(f'output_vac_{port}.txt')
        results.append(f"INSERT INTO benchmark.pomiary (io_method, test_name, run_no, czas_ms, shared_hit, shared_read, uwagi) VALUES ('{io_method}', 'VACUUM (500K)', 1, {et}, 0, 0, 'Vacuum runs');")
    except Exception as e:
        print(f"Error parsing vac runs {port}: {e}")

with open('agent/insert_results.sql', 'w') as f:
    f.write("\n".join(results) + "\n")
